import{updateOverview}from"../pages/OverviewPage/OverviewPage";import{AppState}from"../store/AppState";export function isTodayButAfterNow(e){var t=new Date;return null!=e&&e>t&&e.getFullYear()===t.getFullYear()&&e.getMonth()===t.getMonth()&&e.getDate()===t.getDate()}export function isToday(e){var t=new Date;return null!=e&&e.getFullYear()===t.getFullYear()&&e.getMonth()===t.getMonth()&&e.getDate()===t.getDate()}export function refreshAllowances(){window.external.CalculateAllowances(),AppState.allowances=JSON.parse(window.external.SendAllowanceUpdate()),updateOverview()}